Game.prototype.sliderStates={};Game.prototype.getSliderState=function(sliderId){if(!this.sliderStates[sliderId]){this.sliderStates[sliderId]={currentSlideIndex:0,config:null,container:null,slidesContainer:null,indicators:[]}}return this.sliderStates[sliderId]};Game.prototype.setupSliderTouchEvents=function(container,sliderId){const sliderState=this.getSliderState(sliderId);if(!sliderState.config)return;let startX=0;let startY=0;let isSwiping=false;const minSwipeDistance=50;container.addEventListener("touchstart",e=>{startX=e.touches[0].clientX;startY=e.touches[0].clientY;isSwiping=true},{passive:true});container.addEventListener("touchmove",e=>{if(!isSwiping)return;const currentX=e.touches[0].clientX;const currentY=e.touches[0].clientY;const diffX=startX-currentX;const diffY=startY-currentY;if(Math.abs(diffX)>Math.abs(diffY)&&Math.abs(diffX)>10){e.preventDefault()}},{passive:false});container.addEventListener("touchend",e=>{if(!isSwiping)return;const endX=e.changedTouches[0].clientX;const endY=e.changedTouches[0].clientY;const diffX=startX-endX;const diffY=startY-endY;isSwiping=false;if(Math.abs(diffX)>Math.abs(diffY)&&Math.abs(diffX)>minSwipeDistance){if(diffX>0){this.nextSlide(sliderId)}else{this.previousSlide(sliderId)}}},{passive:true})};Game.prototype.createSliderElement=function(element){if(element.type!=="slider")return;const sliderId=element.id;const sliderState=this.getSliderState(sliderId);sliderState.config=element.config;const sliderContainer=document.createElement("div");sliderContainer.id=element.id;sliderContainer.className="game-element slider-container";sliderContainer.style.position="absolute";sliderContainer.style.width=element.width||"100%";sliderContainer.style.height=element.height||"100%";sliderContainer.style.overflow="hidden";sliderContainer.style.top=`${element.y}%`;sliderContainer.style.left=`${element.x}%`;sliderContainer.style.transform="translate(-50%, -50%)";const slidesContainer=document.createElement("div");slidesContainer.className="slider-slides";slidesContainer.style.width="100%";slidesContainer.style.height="100%";slidesContainer.style.display="flex";slidesContainer.style.transition=`transform ${sliderState.config.transitionDuration||300}ms ease-in-out`;sliderState.config.slides.forEach((slide,index)=>{const slideDiv=document.createElement("div");slideDiv.className="slider-slide";slideDiv.style.width="100%";slideDiv.style.height="100%";slideDiv.style.flexShrink="0";slideDiv.style.position="relative";if(slide.background){this.setupBackground(slideDiv.id||`slide-${index}`,slide.background)}if(slide.elements){slide.elements.forEach(slideElement=>{this.createElement(slideElement,slideDiv)})}slidesContainer.appendChild(slideDiv)});sliderContainer.appendChild(slidesContainer);if(sliderState.config.showIndicators!==false){this.createSliderIndicators(sliderId,sliderContainer)}if(sliderState.config.showArrows!==false){this.createSliderArrows(sliderId,sliderContainer)}sliderState.container=sliderContainer;sliderState.slidesContainer=slidesContainer;this.setupSliderTouchEvents(sliderContainer,sliderId);this.showSlide(sliderId,0);return sliderContainer};Game.prototype.createSliderIndicators=function(sliderId,container){const sliderState=this.getSliderState(sliderId);const indicatorsContainer=document.createElement("div");indicatorsContainer.className="slider-indicators";indicatorsContainer.style.position="absolute";indicatorsContainer.style.bottom="20px";indicatorsContainer.style.left="50%";indicatorsContainer.style.transform="translateX(-50%)";indicatorsContainer.style.display="flex";indicatorsContainer.style.gap="10px";sliderState.config.slides.forEach((_,index)=>{const indicator=document.createElement("div");indicator.className=`slider-indicator ${index===0?"active":""}`;indicator.style.width="12px";indicator.style.height="12px";indicator.style.borderRadius="50%";indicator.style.backgroundColor=index===0?"#007bff":"#ccc";indicator.style.cursor="pointer";indicator.style.transition="background-color 0.3s ease";indicator.addEventListener("click",()=>{this.goToSlide(sliderId,index)});indicatorsContainer.appendChild(indicator);sliderState.indicators.push(indicator)});container.appendChild(indicatorsContainer)};Game.prototype.createSliderArrows=function(sliderId,container){const prevArrow=document.createElement("div");prevArrow.className="slider-arrow slider-arrow-prev";prevArrow.innerHTML="‹";prevArrow.style.position="absolute";prevArrow.style.left="20px";prevArrow.style.top="50%";prevArrow.style.transform="translateY(-50%)";prevArrow.style.fontSize="24px";prevArrow.style.color="#fff";prevArrow.style.cursor="pointer";prevArrow.style.userSelect="none";prevArrow.style.zIndex="10";prevArrow.style.textShadow="0 0 5px rgba(0,0,0,0.5)";prevArrow.addEventListener("click",()=>{this.previousSlide(sliderId)});const nextArrow=document.createElement("div");nextArrow.className="slider-arrow slider-arrow-next";nextArrow.innerHTML="›";nextArrow.style.position="absolute";nextArrow.style.right="20px";nextArrow.style.top="50%";nextArrow.style.transform="translateY(-50%)";nextArrow.style.fontSize="24px";nextArrow.style.color="#fff";nextArrow.style.cursor="pointer";nextArrow.style.userSelect="none";nextArrow.style.zIndex="10";nextArrow.style.textShadow="0 0 5px rgba(0,0,0,0.5)";nextArrow.addEventListener("click",()=>{this.nextSlide(sliderId)});container.appendChild(prevArrow);container.appendChild(nextArrow)};Game.prototype.showSlide=function(sliderId,index){const sliderState=this.getSliderState(sliderId);if(!sliderState.slidesContainer||!sliderState.config)return;const totalSlides=sliderState.config.slides.length;sliderState.currentSlideIndex=Math.max(0,Math.min(index,totalSlides-1));const translateX=-sliderState.currentSlideIndex*100;sliderState.slidesContainer.style.transform=`translateX(${translateX}%)`;if(sliderState.indicators){sliderState.indicators.forEach((indicator,i)=>{indicator.classList.toggle("active",i===sliderState.currentSlideIndex);indicator.style.backgroundColor=i===sliderState.currentSlideIndex?"#007bff":"#ccc"})}if(sliderState.config.onSlideChange){this.executeSliderCallback(sliderState.config.onSlideChange,sliderState.currentSlideIndex)}};Game.prototype.nextSlide=function(sliderId){const sliderState=this.getSliderState(sliderId);const nextIndex=sliderState.currentSlideIndex+1;if(nextIndex<sliderState.config.slides.length){this.showSlide(sliderId,nextIndex)}else if(sliderState.config.loop){this.showSlide(sliderId,0)}};Game.prototype.previousSlide=function(sliderId){const sliderState=this.getSliderState(sliderId);const prevIndex=sliderState.currentSlideIndex-1;if(prevIndex>=0){this.showSlide(sliderId,prevIndex)}else if(sliderState.config.loop){this.showSlide(sliderId,sliderState.config.slides.length-1)}};Game.prototype.goToSlide=function(sliderId,index){this.showSlide(sliderId,index)};Game.prototype.executeSliderCallback=function(callbackConfig,slideIndex){if(!callbackConfig)return;if(Array.isArray(callbackConfig)){callbackConfig.forEach(action=>{if(action.action==="navigate"&&action.target==="scene"){this.switchScene(action.value)}})}};const originalCreateElement=Game.prototype.createElement;Game.prototype.createElement=function(element,parentElement){if(element.type==="slider"){const sliderElement=this.createSliderElement(element);if(sliderElement){parentElement.appendChild(sliderElement)}return}return originalCreateElement.call(this,element,parentElement)};